\section{Preliminaries}\label{sec:prelim}
We assume an integer alphabet $\Sigma = \{1, 2, \ldots, \sigma\}$ with $\sigma$ \emph{characters}. A \emph{string} $Y$ is a sequence of characters numbered from $1$ to $n = |Y|$. By $Y[i]$ we denote the $i$-th symbol of $Y$. For a string $Y$ of length $n$, we denote its \emph{reverse} $Y[n] Y[n-1] \ldots Y[1]$ by $\rev{Y}$. We define $Y[i \dd j]$ to be equal to $Y[i] \dots Y[j]$ which we call a \emph{fragment} of $Y$ if $i \le j$ and to the empty string $\eps$ otherwise. We also use notations $Y[i \dd j)$ and $Y(i\dd j]$ which naturally stand for $Y[i] \dots Y[j-1]$ and $Y[i+1] \dots Y[j]$, respectively. 
We call a fragment $Y[1] \dots Y[j]$ \emph{a prefix} of $Y$ and use a simplified notation $Y[\dd i]$, and a fragment $Y[i] \dots Y[n]$ \emph{a suffix} of $Y$ denoted by $Y[i \dd]$. We say that $X$ is a \emph{substring} of $Y$ if $X = Y[i \dd j]$ for some $1 \le i \le j \le |Y|$. The fragment $Y[i \dd j]$ is called an \emph{occurrence} of $X$. 

For a string $Y$, we define $Y^m$ to be the concatenation of $m$ copies of $Y$.

We say that a fragment $X[i\dd i+\ell)$ is a \emph{previous factor} if 
$X[i\dd i+\ell)=X[i'\dd i'+\ell)$ holds for some $i'\in [1\dd i)$.
The \emph{LZ77 factorization} of $X$ is a factorization $X=F_1\cdots F_z$ into non-empty \emph{phrases}
such tht the $j$th phrase $F_j$ is the longest previous factor starting at position $1+|F_1\cdots F_{j-1}|$; if no previous factor starts there, then $F_j$ consists of a single character.
In the underlying \emph{LZ77 representation}, every phrase $F_j=T[j\dd j+\ell)$ that is a previous fragment is encoded as $(i',\ell)$, where $i'\in [1\dd i)$ satisfies $X[i\dd i+\ell)=X[i'\dd i'+\ell)$.
The remaining length-1 phrases are represented by the underlying character.
We use $\LZ(X)$ to denote the underlying \emph{LZ77 representation} 
and $|\LZ(X)|$ to denote its size (the number of phrases).

\subsection{Edit Distance Alignments}
The \emph{edit distance} $\ed(X, Y)$ between two strings $X$ and $Y$ is defined as the smallest number of character insertions, deletions, and substitutions required to transform $X$ to $Y$. The \emph{Hamming distance} $\hd(X,Y)$ allows substitutions only (and we assume $\hd(X,Y)=\infty$ if $|X|\ne |Y|$).

\begin{definition}
  A sequence $(x_t,y_t)_{t=1}^m$ is an \emph{alignment}
  of $X,Y\in \Sigma^*$ if $(x_1,y_1)=(1,1)$,
  $(x_m,y_m)=(|X|+1,|Y|+1)$, and $(x_{t+1},y_{t+1})\in \{(x_t+1,y_t+1),(x_t+1,y_t),(x_t,y_t+1)\}$ for $t\in [1\dd m)$.
\end{definition}
Given an alignment $\A = (x_t,y_t)_{t=1}^m$ of strings $X,Y\in \Sigma^*$,
for every $t\in [1\dd m)$:
\begin{itemize}
  \item If $(x_{t+1},y_{t+1})=(x_t+1,y_t)$, we say that $\A$ \emph{deletes} $X[x_t]$,
  \item If $(x_{t+1},y_{t+1})=(x_t,y_t+1)$, we say that $\A$ \emph{deletes} $Y[y_t]$,
  \item If $(x_{t+1},y_{t+1})=(x_t+1,y_t+1)$, we say that $\A$ \emph{aligns} $X[x_t]$ and $Y[y_t]$, denoted $X[x_t] \sim_\A Y[y_t]$. If~additionally $X[x_t]= Y[y_t]$, we say that $\A$ \emph{matches} $X[x_t]$ and $Y[y_t]$, denoted $X[x_t] \simeq_\A Y[y_t]$.
  Otherwise, we say that $\A$ \emph{substitutes} $X[x_t]$ for $Y[y_t]$.
\end{itemize}

The \emph{cost} of an edit distance alignment $\A$ is the total number characters that $\A$ deletes or substitutes.
We denote the cost by $\cost_{X,Y}(\A)$, omitting the subscript if $X,Y$ are clear from context.
The cost of an alignment $\A=(x_t,y_t)_{t=1}^m$ is at least its width $\width(\A)=\max_{t=1}^m |x_t-y_t|$.
Observe that $\ed(X,Y)$ can be defined as the minimum cost of an alignment of $X$ and~$Y$.

Given an alignment $\A=(x_t,y_t)_{t=1}^m$ of $X,Y\in \Sigma^+$, we partition the elements $(x_t,y_t)$ of $\A$
into \emph{matches} (for which $X[x_t]\simeq_{\A} Y[y_t]$) and \emph{breakpoints} (the remaining elements).
We denote the set of matches and breakpoints by $\mtch_{X,Y}(\A)$ and $\brkp_{X,Y}(\A)$, respectively,
omitting the subscripts if the strings $X,Y$ are clear from context.

We call $M\sub [1\dd |X|]\times [1\dd |Y|]$ a \emph{non-crossing matching} of $X,Y\in \Sigma^*$
if $X[x]=Y[y]$ holds for all $(x,y)\in M$ and there are no distinct pairs $(x,y),(x',y')\in M$ with $x\le x'$ and $y\ge y'$.

\section{Technical Overview}\label{sec:overview}

\begin{restatable}[Greedy alignment]{definition}{defgreedy}\label{def:greedy_alignment}
We say that an alignment $\A$ of two strings $X, Y\in \Sigma^*$ is \emph{greedy} if  $X[x] \ne Y[y]$ holds for every $(x,y)\in \brkp(\A) \cap ([1\dd |X|]\times [1\dd |Y|])$.
Given $k\ge 0$, we denote by $\ga_k(X,Y)$ the set of all greedy alignments $\A$ of $X,Y$
satisfying $\cost(\A)\le k$.
\end{restatable}

\begin{restatable}{definition}{defnoncrossing}
Let $M$ be a non-crossing matching of strings $X,Y\in \Sigma^*$.
We define $X^M,Y^M$ to be the strings obtained from $X,Y$ by replacing $X[x]$ and $Y[y]$
with $\# \notin \Sigma$ for every $(x,y)\in M$. 
We refer to $\#$ as a \emph{dummy symbol} and to maximal blocks of $\#$'s as \emph{dummy segments}.
\end{restatable}

\begin{restatable}{lemma}{lmgreedyalg}\label{lm:greedyalg}
	For all $X,Y\in \Sigma^*$ and $k\in \Zp$, the set $\brkp_k(X,Y) = \hspace{-.4cm}  \bigcup\limits_{\A \in \ga_k(X,Y)} \hspace{-.4cm} \brkp(\A)$ is of size~$\Oh(k^5)$.
\end{restatable}

\begin{restatable}{proposition}{prpalg}\label{prp:alg}
For every constant $\delta \in (0,1)$, there exists a constant $c$ and an algorithm $\Alg$ that, given an integer $n$, a seed $r$ of $\Oh(\log^2 n)$ random bits, and a string $S\in \Sigma^{\le n}$, outputs a $3n$-step complete walk $\Alg(n,r,S)$ over $S$ satisfying the following property for all  $X,Y\in \Sigma^{\le n}$ and the zip alignment $\A_\Alg$ of  $\Alg(n,r,X)$ and $\Alg(n,r,Y)$:
\[\Pr_r\left[ \A_\Alg\in \ga_{c\cdot \ed(X,Y)^2}(X,Y)\text{ and }\width(\A_\Alg)\le c\cdot\ed(X,Y)\right] \ge 1-\delta.\]
Moreover, $\Alg$ is an $\Oh(\log^2 n)$-bit streaming algorithm that costs $\Oh(n\log n)$ time and reports any element $s_t\in [1\dd |S|]$ of $\Alg(n,r,S)$ while processing the corresponding character $S[s_t]$.
\end{restatable}

\section{Compressed String Representation}\label{sec:compr}

\begin{proposition}\label{prp:RLSLP}
    In the $w$-bit word RAM model, every string $X\in \Sigma^n$ satisfying $w = \Omega(\log n + \log |\Sigma|)$, $z = |\LZ(X)|$, and $\rev{z}=|\LZ(\rev{X})|$ has a representation $\CR(X)$ that uses 
 $\Oh(z \log^2 n)$ space and supports the following queries:
    \begin{enumerate}[label=\textrm{(\alph*)}]
        \item retrieve $n=|X|$, in $\Oh(1)$ time;\label{it:length}
        \item given $i\in [1\dd n]$, retrieve $X[i]$, in $\Oh(\log n)$ time;\label{it:access}
        \item given $i,j\in [1\dd n]$, compute $\LCE(X[i\dd n],X[j\dd n])$, in $\Oh(\log n)$ time;\label{it:lce}
        \item given $i,j\in [1\dd n]$, compute $\LCE(\rev{X}[i\dd n],\rev{X}[j\dd n])$, in $\Oh(\log n)$ time;\label{it:rlce}
        \item compute $\LZ(X)$, in $\Oh(z\log^4 n)$ time;\label{it:lz}
        \item compute $\LZ(\rev{X})$, in $\Oh(\rev{z}\log^4 n)$ time;\label{it:rlz}
        \item given $i,j\in [1\dd n]$ with $i\le j$, compute $\CR(X[i\dd j])$, in $\Oh(z \log^4 n)$ time.\label{it:extract}
    \end{enumerate}
    Moreover, $\CR(X)$ can be constructed:
    \begin{enumerate}[label=\textrm{(\alph*)},resume]
        \item in $\Oh(f \log^2 n)$ time given an $f$-phrase LZ-like representation of $X$ or $\rev{X}$;\label{it:fromLZ}
        \item in $\Oh(z\log^4 n)$ time given $\CR(X[1\dd i))$ and $\CR(X[i\dd n])$ for some $i\in [1\dd n]$.\label{it:concat}
    \end{enumerate}
\end{proposition}

\section{Greedy Alignments and Encodings}\label{sec:greedy}

For strings $X,Y\in \Sigma^*$ and an integer $k\ge \ed(X,Y)$, we define a set \[\mtch_k(X,Y) = \bigcap_{\A \in \ga_k(X,Y)} \mtch_{X,Y}(\A)\] of \emph{common matches} of all alignments $\A\in \ga_k(X,Y)$;
note that it forms a non-crossing matching of~${X,Y}$.

Additionally, for a string $Z \in (\Sigma \cup \#)^*$, we define $\num(Z)$ as a string obtained from $Z$ by replacing the $i$th leftmost occurrence of $\#$ in it with a unique dummy symbol $\#_i \notin \Sigma$. 

\newcommand{\RS}{\mathsf{RS}}
\begin{proposition}\label{prop:rank}
Consider a string $S\in (\Sigma\cup\{\#\})^n$ with $s$ dummy segments.
Given the sorted list of dummy segments in $S$, one can in $\Oh(s)$ time construct a data structure $\RS_\#(S)$ supporting the following queries in $\Oh(\log s)$ time: 
\begin{enumerate}
  \item $\mathbf\rank_\#(S,i)$: Given $i\in [1\dd n+1]$, return $|\{i' \in [1\dd i) : S[i'] = \#\}|$.
 \item $\mathbf\select_\#(S,j)$: Given $j\in [1\dd \rank_\#(S,n)]$, return the $j$th smallest element of $\{i \in [1\dd n] : S[i] = \#\}$.
\end{enumerate}
\end{proposition}

\begin{definition}\label{def:masked_encoding}
For a non-crossing matching $M$ of strings $X,Y\in \Sigma^*$
we set (cf.~\cref{prp:RLSLP}):  \[\Enc^{M}(X,Y):=\left(\CR(X^MY^M), \RS_\#(X^M), \RS_\#(Y^M) \right).\]
\end{definition}

\begin{corollary}\label{cor:ED}
Given an integer $k> 0$ and the encoding $\Enc^{M}(X,Y)$ for a non-crossing matching $M$ of strings $X,Y\in \Sigma^{\le n}$, one can in $\Oh(k^2\log n)$ time compute a integer $d\in [0\dd k+1]$ such that
\[ d = \begin{cases}
  \ed(X,Y) & \text{if }\ed(X,Y)\le k\text{ and }M\sub \mtch_k(X,Y),\\
  k+1 & \text{if }\ed(X,Y)>k.
\end{cases}\]
\end{corollary}

\subsection{Greedy Encoding and Its Size}
\begin{definition}\label{def:greedy_encoding}
	For strings $X,Y\in \Sigma^*$ and an integer $k$, we define the \emph{greedy encoding} 
	\[\gr_k(X,Y)=\begin{cases}
	  \Enc^{\mtch_k(X,Y)}(X,Y) & \text{if }k\ge \ed(X,Y),\\
	  \bot & \text{otherwise.}\end{cases}\]
\end{definition}

\subsection{Construction of greedy encodings}\label{sec:greedyalg}

\begin{proposition}\label{prp:greedify}
Consider a non-crossing matching $M$ of strings $X,Y\in \Sigma^{\le n}$ and an integer $k\in \Zp$
such that $M\sub \mtch_k(X,Y)$ holds if $\ed(X,Y)\le k$.
Given $k$ and $\Enc^M(X,Y)$, the greedy encoding $\gr_k(X,Y)$ can be computed in $\tOh(zk+k^2 + |\brkp_k(X,Y)|)$ time and $\tOh(z+k^2)$ space, where $z = |\LZ(X^MY^M)|$.
\end{proposition}

\subsection{Concatenations and Quasi-greedy Alignments}\label{sec:quasi}

\begin{definition}[Quasi-greedy alignment]\label{def:quasi_greedy_alignment}
  We say that an alignment $\A$ of two strings $X, Y\in \Sigma^*$ is \emph{quasi-greedy} if it satisfies at least one of the following symmetric conditions:
  \begin{itemize}
    \item there exists $\delta \in [1\dd |X|+1]$ such that $(\delta,1)\in \A$ and $X[x] \neq Y[y]$ holds for every $(x,y) \in \brkp(\A) \cap ([\delta\dd|X|]\times [1\dd |Y|])$;
    \item there exists $\delta \in [1\dd |Y|+1]$ such that $(1,\delta)\in \A$ and $X[x] \neq Y[y]$ holds for every $(x,y) \in \brkp(\A) \cap ([1\dd|X|]\times [\delta\dd |Y|])$;
  \end{itemize}
Given $k\ge 0$, we denote by $\qga_k(X,Y)$ the set of all quasi-greedy alignments $\A$ of $X,Y$ with $\cost(\A)\le k$.
\end{definition}

  For strings $X,Y\in \Sigma^*$ and an integer $k\ge \ed(X,Y)$, we define a set \[\qmtch_k(X,Y) = \bigcap_{\A \in \qga_k(X,Y)} \mtch_{X,Y}(\A)\] of \emph{common matches} of all alignments $\A\in \qga_k(X,Y)$.

  \begin{definition}
    For strings $X,Y\in \Sigma^*$ and an integer $k$, we define the \emph{quasi-greedy encoding} 
    \[\qgr_k(X, Y) = \begin{cases} \Enc^{\qmtch_k(X,Y)}(X,Y)&\text{if }\ed(X,Y)\le k,\\
      \bot &\text{otherwise.}\end{cases}\]
  \end{definition}

  \begin{corollary}\label{cor:qgr_to_gr}
    Consider strings $X,Y \in \Sigma^{\le n}$. Define $X' = \$_1 X$ and $Y' = \$_2 Y$, where $\$_1 \neq \$_2$ are special symbols not in $\Sigma$. Let $M' = \mtch_{k+1}(X',Y')$ and $M = \qmtch_k(X,Y)$. The following properties hold:
\begin{enumerate}[label=\textrm{(\alph*)}]
\item Given the dummy segments for one of the strings $X^{M}, (X')^{M'}$, the dummy segments for the other string can be constructed in $\Oh(k)$ time and space;\label{it:dummy} 
\item  Given one of the encodings $\qgr_k(X, Y), \gr_{k+1}(X', Y')$, the other encoding can be constructed in $\Oh(k^2 \log^4 n)$ time and space;\label{it:encodings}
\item The quasi-greedy encoding $\qgr_k(X, Y)$ occupies $\Oh(k^2 \log^4 n)$ space. \label{it:qga_space} 
\end{enumerate}
\end{corollary}

\section{Edit Distance Sketches}\label{sec:sketches}
\subsection{CGK embedding}\label{sec:CGK}

\begin{definition}[Complete walk]\label{def:walk}
For a string $S\in \Sigma^*$, we say that $(s_t)_{t=1}^{m+1}$ is an \emph{$m$-step complete walk over $S$} if $s_1 = 1$, $s_{m+1} = |S|+1$, and $s_{t+1}\in \{s_t,s_t+1\}$ for $t\in [1\dd m]$.
\end{definition}

\begin{definition}[Zip alignment]\label{def:zip}
	The \emph{zip alignment} of $m$-step complete walks $(x_t)_{t=1}^{m+1}$ and $(y_t)_{t=1}^{m+1}$ over ${X,Y\in \Sigma^*}$
	is obtained by removing repeated entries in $(x_t,y_t)_{t=1}^{m+1}$.
\end{definition}

\subsection{Context encoding}\label{sec:cover}

For a string $S\in \Sigma^*$, define $\maxLZ(S) = \max_{[\ell\dd r)\sub [1\dd |S|]} |\LZ(\rev{S[\ell \dd r)})|$. 

\newcommand{\Ctx}[3]{C_{#1}(#2,#3)}
\newcommand{\Dtx}[3]{C^2_{#1}(#2,#3)}

\begin{definition}[(Double) Context]
	Consider a string $S\in \Sigma^*$ and an integer $k\in \Zp$.
	For a position $p\in [1\dd |S|]$, we define the \emph{context} $\Ctx{k}{S}{p}$
	as the longest prefix $S[p\dd q)$ of $S[p \dd |S|]$ such that $\maxLZ(S[p\dd q))\le k$
	and the \emph{double context} $\Dtx{k}{S}{p}$ as the longest prefix $S[p\dd q)$ of $S[p\dd |S|]$ such that $\maxLZ(S[p\dd r))\le k$ and $\maxLZ(S[r\dd q))\le k$ for some $r\in [p\dd q]$.
\end{definition}

For integers $t<v$, let $\mu(t,v)$ denote the integer $w\in [t\dd v)$ divisible by the largest power~of~2.

\begin{algorithm}[ht]
	\SetKwInput{KwData}{Randomness}
    \SetAlgoNoLine
	\SetKwBlock{Begin}{}{end}
	\KwIn{An integer $k\in \Zz$, a string $S\in \Sigma^*$, and a complete walk $(s_t)_{t=1}^{m+1}$ over $S$.}
	\KwOut{The string $\bCGK_k(W)[1\dd m]$.}
	\vspace{.25cm}
	$\bCGK_k(W) := \bot^{m}$, where $\bot = (\LZ(\eps),0)$\;
	$s_0 : =0;\; \mu_0 := 0;\; u := 0$\;
	\For{$t := 1$ \KwTo $m$} {
		\If{$s_t \le |S|$} {
			$\mu_t := \mu(t,\min\{v\in [1\dd m+1] : s_v = s_t + |\Ctx{k}{S}{s_t}|\})$\;
			\If{$\mu_t > \mu_{t-1}$}{
				$\bCGK_k(W)[t] := \left(\LZ\left(\rev{\Dtx{k}{S}{s_t}}\right),s_{t}-s_{u}\right)$\;
				$u := t$\;
			}
		}
	}
	\Return{$\bCGK_k(W)$}\;
	\caption{Function $\bCGK$}\label{alg:bCGK}
\end{algorithm}

We say that a position $S[s]$ is covered by a fragment $S[\ell\dd r)$ if $\ell\le s < r$.

\begin{lemma}\label{lem:cover}
Consider $\bCGK_{k}(W)$ constructed for an integer $k\in \Zz$ and an $m$-complete walk $W=(s_t)_{t=1}^{m+1}$ over $S\in \Sigma^*$. Each position $s\in [1\dd |S|]$ satisfies
\begin{multline*}1\le |\{t\in [1\dd m] : \bCGK_k(W)[t]\ne \bot\text{ and }\Ctx{k}{S}{s_t}\text{ covers }S[s]\}| \le 	\\ \le |\{t\in [1\dd m] : \bCGK_k(W)[t]\ne \bot\text{ and }\Dtx{k}{S}{s_t}\text{ covers }S[s]\}| \le \Oh(\log m)
\end{multline*}
\end{lemma}

Let $\A$ be an alignment between $X,Y\in \Sigma^*$.
We define $\brkp_X(\A) = \{x : (x,y)\in \brkp(\A)\}\cap [1\dd |X|]$.
Moreover, for two alignments $\A, \A'$ between $X,Y\in \Sigma^*$, we define $\Delta_X(\A,\A')$
to contain $x\in [1\dd |X|]$ unless $(x,y)\in \mtch(\A)\cap \mtch(\A')$ for some $y\in [1\dd |Y|]$.

\begin{lemma}\label{lem:close}
Let $b\in \mathbb{Z}_{+}$ and $\A,\A'$ be greedy alignments of strings $X$ and $Y$.
The positions in $\Delta_X(\A,\A')$ can be covered by at most $\cost(\A)+\frac1b\cost(\A')$ contexts
$\Ctx{\width(\A)+\width(\A')+2b}{X}{\cdot}$. 

Moreover, if $b > \cost(\A')$, then the positions in $\Delta_X(\A,\A')$ can be covered 
by contexts $\Ctx{\width(\A)+\width(\A')+2b}{X}{x}$ with $x\in \brkp_X(\A)$.
\end{lemma}

\begin{lemma}\label{lem:bcgk}
Let $\A_W$ be the zip alignment of $m$-complete walks $W_X = (x_t)_{t=1}^{m+1}$, $W_Y=(y_t)_{t=1}^{m+1}$ over strings $X,Y\in \Sigma^*$, and let $k'\in \Zp$.
If $\A_W$ is greedy, then $\brkp_X(\A_W)\sub P_X$, where $P_X$ is the set of positions $x\in [1\dd |X|]$ such that $X[x]$ is covered by $\Dtx{k'}{X}{x_t}$ for some $t\in [1\dd m]$ with $\bot \ne \bCGK_{k'}(W_X)[t] \ne \bCGK_{k'}(W_Y)[t]$.
Moreover, for every positive integer $k\ge \ed(X,Y)$ such that $k'\ge \width(\A_W)+5k$:
\begin{itemize}
	\item every $\A\in\ga_k(X,Y)$ satisfies $\Delta_X(\A,\A_W)\sub P_X$,
	\item $\hd(\bCGK_{k'}(X),\bCGK_{k'}(Y)) \le c(k+\frac1k\cost(\A_W))\log m$ holds for a sufficiently large constant $c$.
\end{itemize}
\end{lemma}

\begin{lemma}\label{cor:bcgkp_construction}
	Given integers $n\ge k \ge 1$, a seed $r$ of $\Oh(\log^2 n)$ random bits, and streaming access to a string $S\in \Sigma^{\le n}$, the string $\bCGK_k(\Alg(S,n,r))$ can be computed in $\tOh(k)$ space and $\tOh(nk)$ time.
	\end{lemma}

\subsection{Applications of Hamming distance sketches}

For two equal-length strings $X,Y$, the set of \emph{mismatch positions} is defined as $\MP(X,Y)=\{i\in [1\dd |X|]: X[i]\ne Y[i]\}$
and the \emph{mismatch information} 
$\MI(X,Y) = \{(i,X[i],Y[i]) : i\in \MP(X,Y)\}$.

\begin{theorem}\label{thm:skH}
	For every constant $\delta\in (0,1)$, there exists a sketch $\skH_k$ (parameterized by integers $n\ge k\ge 1$,
	an alphabet $\Sigma=[0\dd \sigma)$, and a seed of $\Oh(\log (n\log \sigma))$ random bits) such that:
	\begin{enumerate}
		\item The sketch $\skH_k(S)$ of a string $S\in \Sigma^{n}$ takes $\Oh(k\log (n\sigma))$ bits. Given streaming access to $S$, it can be constructed in $\Oh(n\log (n\sigma) \log (n\log \sigma))$ time using $\Oh(k\log (n\sigma))$ bits of space.
		\item There exists a decoding algorithm that, given $\skH_k(X)$ and $\skH_k(Y)$ for strings $X,Y\in \Sigma^{n}$, with probability at least $1-\delta$ either returns $\MI(X,Y)$ or certifies that $\hd(X,Y)>k$.
		The algorithm uses $\Oh(k \log (n\sigma) \log^2 (n\log \sigma))$ time and $\Oh(k \log (n\sigma))$ bits of space. 
	\end{enumerate}
\end{theorem}

Next, consider an alphabet $\hat{\Sigma}:=\Sigma\times \Zz$ 
and a function $\pi : \hat{\Sigma} \to \Zz$ defined so that $\pi((a,v))=v$ for $(a,v)\in \hat{\Sigma}$
and $\pi(S)=\sum_{i=1}^{|S|} \pi(S[i])$ for $S\in \hat{\Sigma}^*$.  
For two strings $X,Y\in \hat{\Sigma}^*$ of the same length, we define the \emph{prefix mismatch information}
\[\PMI(X,Y) = \{(i,\pi(X[1\dd i)),\pi(Y[1\dd i))) : i\in \MP(X,Y)\}.\]

\begin{proposition}\label{prp:mpi}
For every constant $\delta\in (0,1)$, there exists a sketch $\skL_k$ (parameterized by integers $n\ge k\ge 1$, an alphabet $\hat{\Sigma}=[1\dd \sigma]\times [0\dd n^{\Oh(1)}]$, and a seed of $\Oh(\log (n\log \sigma))$ random bits) such that:
\begin{enumerate}
	\item The sketch $\skL_k(S)$ of a string $S\in \hat{\Sigma}^n$ takes $\Oh(k\log^2 n)$ bits. Given streaming access to $S$, it can be constructed in $\Oh(n \log n \log(n\log \sigma) + n\log^2 n)$ time using $\Oh(k\log^2 n + \log n\log(n\log \sigma))$ bits of space.
	\item There exists a decoding algorithm that, given the sketches $\skL_k(X)$ and $\skL_k(Y)$ of strings $X,Y\in \hat{\Sigma}^{n}$
	satisfying $\pi(X),\pi(Y)< n$, with probability at least $1-\delta$ either returns $\PMI(X,Y)$ or certifies that $\hd(X,Y)>k$.
	The algorithm uses $\Oh(k \log^4 n)$ time and $\Oh(k \log^2 n)$ bits of space. 
\end{enumerate}
\end{proposition}
